package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_wishlist_item",uniqueConstraints= @UniqueConstraint(name="uq_wishlist_customer_product",columnNames={"customer_profile_id","product_id"})) public class CustomerWishlistItem {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="wishlist_item_id") private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_profile_id") private CustomerProfile customer; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @PrePersist void add(){createdAt=OffsetDateTime.now();} public CustomerWishlistItem(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public CustomerProfile getCustomer(){return customer;} public void setCustomer(CustomerProfile v){customer=v;} public Product getProduct(){return product;} public void setProduct(Product v){product=v;} public OffsetDateTime getCreatedAt(){return createdAt;}}